public class Person {
    private String name;
    private int age;

    // Constructor with name only
    public Person(String name) {
        this(name, 0);  // Calls the two-argument constructor
    }

    // Constructor with name and age
    public Person(String name, int age) {
        this.name = name;
        this.age = age;
    }
}

// Usage
Person p1 = new Person("Alice");        // Uses the first constructor
Person p2 = new Person("Bob", 30);      // Uses the second constructor

public class Employee {
    private String name;
    private int id;
    private String department;

    public Employee(String name, int id, String department) {
        this.name = name;
        this.id = id;
        this.department = department;
    }

    public Employee(String name, int id) {
        this(name, id, "General");  // Calls the three-argument constructor
    }

    public Employee(String name) {
        this(name, 0);  // Calls the two-argument constructor
    }
}

public class Singleton {
    private static Singleton instance;

    private Singleton() {
        // Private constructor to prevent instantiation
    }

    public static Singleton getInstance() {
        if (instance == null) {
            instance = new Singleton();
        }
        return instance;
    }
}

public class Person {
    private final String name;
    private final int age;

    public Person(String name, int age) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty");
        }
        if (age < 0 || age > 150) {
            throw new IllegalArgumentException("Age must be between 0 and 150");
        }
        this.name = name;
        this.age = age;
    }
}
